"use strict";

const https = require("https");
const zlib = require("zlib");
const { URL } = require("url");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const PAGE_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u ? String(u).replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorbPair(pair) {
    const i = pair.indexOf("=");
    if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
  }
  absorb(res) {
    const lines =
      res && res.headers && typeof res.headers.getSetCookie === "function"
        ? res.headers.getSetCookie()
        : [];
    for (const line of lines) this.absorbPair(String(line).split(";")[0]);
  }
  absorbHeaders(headers) {
    const lines = (headers && headers["set-cookie"]) || [];
    for (const line of lines) this.absorbPair(String(line).split(";")[0]);
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function httpsGetText(targetUrl, jar, redirectsLeft) {
  return new Promise((resolve, reject) => {
    const req = https.get(
      targetUrl,
      {
        headers: {
          ...PAGE_HEADERS,
          "accept-encoding": "gzip, deflate, br",
          cookie: jar.toString(),
        },
        timeout: 20000,
      },
      (res) => {
        jar.absorbHeaders(res.headers);
        const status = res.statusCode || 0;
        if (
          status >= 300 &&
          status < 400 &&
          res.headers.location &&
          redirectsLeft > 0
        ) {
          res.resume();
          resolve(
            httpsGetText(new URL(res.headers.location, targetUrl).toString(), jar, redirectsLeft - 1)
          );
          return;
        }
        let stream = res;
        const enc = String(res.headers["content-encoding"] || "").toLowerCase();
        if (enc === "gzip") stream = res.pipe(zlib.createGunzip());
        else if (enc === "deflate") stream = res.pipe(zlib.createInflate());
        else if (enc === "br" && typeof zlib.createBrotliDecompress === "function") {
          stream = res.pipe(zlib.createBrotliDecompress());
        }
        const chunks = [];
        stream.on("data", (c) => chunks.push(c));
        stream.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
        stream.on("error", reject);
        res.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("Request timed out")));
    req.on("error", reject);
  });
}

async function fetchPage(url, jar, hasData, attempts = 5) {
  let lastHtml = "";
  for (let i = 0; i < attempts; i++) {
    try {
      if (typeof fetch === "function") {
        const ctl = new AbortController();
        const to = setTimeout(() => ctl.abort(), 20000);
        const res = await fetch(url, {
          headers: { ...PAGE_HEADERS, cookie: jar.toString() },
          redirect: "follow",
          signal: ctl.signal,
        });
        clearTimeout(to);
        jar.absorb(res);
        lastHtml = await res.text();
      } else {
        lastHtml = await httpsGetText(url, jar, 5);
      }
      if (hasData(lastHtml)) return lastHtml;
    } catch {

    }
    await new Promise((r) => setTimeout(r, 700));
  }
  return lastHtml;
}

function* jsonBlobs(html) {
  const re = /<script[^>]*type="application\/json"[^>]*>([\s\S]*?)<\/script>/g;
  let m;
  while ((m = re.exec(html))) yield m[1];
}

function walkObjects(node, depth, visit) {
  if (depth > 26) return;
  if (typeof node === "string") {
    const t = node.trim();
    if (
      t.length > 2 &&
      t.length < 2_000_000 &&
      ((t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]")))
    ) {
      try {
        walkObjects(JSON.parse(t), depth + 1, visit);
      } catch {

      }
    }
    return;
  }
  if (!node || typeof node !== "object") return;
  visit(node);
  for (const v of Object.values(node)) walkObjects(v, depth + 1, visit);
}

function isPostObject(o) {
  return (
    !Array.isArray(o) &&
    typeof o.code === "string" &&
    o.user &&
    typeof o.user === "object" &&
    (o.caption !== undefined ||
      o.image_versions2 !== undefined ||
      o.video_versions !== undefined ||
      o.text_post_app_info !== undefined)
  );
}

function collectPosts(html) {
  const posts = [];
  const seen = new Set();
  for (const blob of jsonBlobs(html)) {
    let root;
    try {
      root = JSON.parse(blob);
    } catch {
      continue;
    }
    walkObjects(root, 0, (o) => {
      if (isPostObject(o) && !seen.has(o.code)) {
        seen.add(o.code);
        posts.push(o);
      }
    });
  }
  return posts;
}

function bestImageFrom(media) {
  const cands =
    media && media.image_versions2 && Array.isArray(media.image_versions2.candidates)
      ? media.image_versions2.candidates
      : [];
  if (!cands.length) return null;
  return cands
    .slice()
    .sort((a, b) => (b.width || 0) * (b.height || 0) - (a.width || 0) * (a.height || 0))[0].url;
}

function shapePost(post) {
  const info = post.text_post_app_info || {};
  const videos = (post.video_versions || [])
    .filter((v) => v && v.url)
    .map((v) => ({ type: v.type, width: v.width || null, height: v.height || null, url: v.url }))
    .sort((a, b) => (b.width || 0) * (b.height || 0) - (a.width || 0) * (a.height || 0));

  let carousel = null;
  if (Array.isArray(post.carousel_media)) {
    carousel = post.carousel_media.map((child) => ({
      id: child.pk ? String(child.pk) : null,
      type: child.video_versions && child.video_versions.length ? "video" : "photo",
      image: bestImageFrom(child),
      video:
        child.video_versions && child.video_versions.length
          ? child.video_versions
              .slice()
              .sort((a, b) => (b.width || 0) * (b.height || 0) - (a.width || 0) * (a.height || 0))[0].url
          : null,
    }));
  }

  const user = post.user || {};
  return {
    id: post.pk ? String(post.pk) : null,
    code: post.code || null,
    type: videos.length ? "video" : post.image_versions2 ? "image" : "text",
    text: post.caption && post.caption.text ? post.caption.text : "",
    likes: typeof post.like_count === "number" ? post.like_count : null,
    replies:
      typeof info.direct_reply_count === "number"
        ? info.direct_reply_count
        : typeof post.direct_reply_count === "number"
          ? post.direct_reply_count
          : null,
    reposts: typeof info.repost_count === "number" ? info.repost_count : null,
    quotes: typeof info.quote_count === "number" ? info.quote_count : null,
    shares: typeof info.share_count === "number" ? info.share_count : null,
    reshares: typeof info.reshare_count === "number" ? info.reshare_count : null,
    isReply: info.is_reply === true,
    takenAt: typeof post.taken_at === "number" ? post.taken_at : null,
    author: {
      id: user.pk ? String(user.pk) : null,
      username: user.username || null,
      fullName: user.full_name || null,
      avatar: user.profile_pic_url || null,
      verified: typeof user.is_verified === "boolean" ? user.is_verified : null,
    },
    media: {
      image: bestImageFrom(post),
      video: videos.length ? videos[0].url : null,
      videoVersions: videos,
      carousel,
    },
    download: {
      video: videos.length ? videos[0].url : null,
      image: bestImageFrom(post),
    },
    url: post.code ? `https://www.threads.com/t/${post.code}` : null,
  };
}

function parseCode(input) {
  const s = String(input || "").trim();
  const m = s.match(/threads\.(?:com|net)\/(?:t|post)\/([A-Za-z0-9_-]+)/);
  if (m) return m[1];
  const m2 = s.match(/threads\.(?:com|net)\/@[^/]+\/post\/([A-Za-z0-9_-]+)/);
  if (m2) return m2[1];
  if (/^[A-Za-z0-9_-]{8,15}$/.test(s)) return s;
  return null;
}

module.exports = async function fetchSelf(input) {
  try {
    const code = parseCode(input);
    if (!code) throw new Error("Invalid Threads post URL or code");

    const jar = new Jar();
    const url = `https://www.threads.com/t/${code}`;
    const html = await fetchPage(
      url,
      jar,
      (h) => collectPosts(h).some((p) => p.code === code)
    );
    const posts = collectPosts(html);
    const main = posts.find((p) => p.code === code);
    if (!main) {
      throw new Error(
        "Could not extract this post -- it may be deleted, or Threads changed its page format"
      );
    }

    const shaped = shapePost(main);
    const repliesPreview = posts
      .filter((p) => p.code !== code)
      .slice(0, 10)
      .map(shapePost);

    const carousel = Array.isArray(shaped.media.carousel) ? shaped.media.carousel : null;
    let video = cleanUrl(shaped.download.video);
    if (!video && carousel) {
      const firstCarouselVideo = carousel.find((c) => c && c.video);
      if (firstCarouselVideo) video = cleanUrl(firstCarouselVideo.video);
    }

    const images = [];
    if (shaped.download.image) images.push(cleanUrl(shaped.download.image));
    if (carousel) {
      for (const child of carousel) {
        if (child && child.image) images.push(cleanUrl(child.image));
      }
    }
    const uniqImages = [...new Set(images.filter(Boolean))];

    const mp4s = [
      ...new Set(
        (shaped.media.videoVersions || []).map((v) => cleanUrl(v.url)).filter(Boolean)
      ),
    ];
    if (video && !mp4s.includes(video)) mp4s.unshift(video);

    if (!video && !uniqImages.length) {
      throw new Error("Threads media not found (text-only post or restricted).");
    }

    const data = {
      id: shaped.id || null,
      title: shaped.text ? shaped.text : "Threads Post",
      thumbnail: cleanUrl(shaped.media.image) || uniqImages[0] || null,
      download: { video: video || null },
    };

    if (video) {
      data.extra = { mp4: mp4s.slice(0, 10) };
    }

    if (!video && uniqImages.length) {
      data.images = uniqImages.slice(0, 20);
    }

    data.extra = {
      ...(data.extra || {}),
      id: shaped.id || null,
      code: shaped.code || null,
      type: shaped.type || null,
      author: shaped.author || null,
      likes: typeof shaped.likes === "number" ? shaped.likes : null,
      replies: typeof shaped.replies === "number" ? shaped.replies : null,
      reposts: typeof shaped.reposts === "number" ? shaped.reposts : null,
      quotes: typeof shaped.quotes === "number" ? shaped.quotes : null,
      shares: typeof shaped.shares === "number" ? shaped.shares : null,
      reshares: typeof shaped.reshares === "number" ? shaped.reshares : null,
      takenAt: typeof shaped.takenAt === "number" ? shaped.takenAt : null,
      url: shaped.url || url,
      image: cleanUrl(shaped.download.image),
      videoVersions: (shaped.media.videoVersions || []).map((v) => ({
        type: v.type != null ? v.type : null,
        width: v.width || null,
        height: v.height || null,
        url: cleanUrl(v.url),
      })),
      carousel: carousel
        ? carousel.map((c) => ({
            id: c.id || null,
            type: c.type || null,
            image: cleanUrl(c.image),
            video: cleanUrl(c.video),
          }))
        : null,
      repliesPreview: repliesPreview.map((p) => ({
        id: p.id || null,
        code: p.code || null,
        type: p.type || null,
        text: p.text || "",
        likes: typeof p.likes === "number" ? p.likes : null,
        author: p.author || null,
        download: {
          video: cleanUrl(p.download && p.download.video),
          image: cleanUrl(p.download && p.download.image),
        },
        url: p.url || null,
      })),
    };

    return {
      success: true,
      source: "Threads",
      data,
    };
  } catch (e) {
    if (/^Threads Error:/.test(e.message)) throw e;
    throw new Error("Threads Error: " + e.message);
  }
};
